// Apify Reddit Scraper 결과를 표준 5개 VOC 스키마(VOC_ID | CATEGORY | CONTENT_TYPE | CONTENT | PARENT_ID)로 정규화합니다.
const vocRows = [];
const category = $('Execute Workflow Trigger').first().json?.category || 'Community/Forum';

for (const item of $input.all()) {
  const d = item.json;
  if (!d || (!d.id && !d.parsedId)) continue;

  const rawId = d.parsedId || d.id;
  const dataType = (d.dataType || d.type || '').toLowerCase();

  // 1. 게시물 본문(Post)인 경우 (제목 + 본문 병합)
  if (dataType === 'post' || d.title) {
    const postId = `RD_POST_${rawId}`;
    const title = d.title || '';
    const body = d.body || d.selftext || d.text || '(본문 텍스트 없음)';

    vocRows.push({
      json: {
        VOC_ID: postId,
        CATEGORY: category,
        CONTENT_TYPE: 'POST',
        CONTENT: `[Title] ${title}\n[Body] ${body}`,
        PARENT_ID: null
      }
    });
  } 
  // 2. 댓글(Comment)인 경우 (상위 게시물 ID를 PARENT_ID로 매핑)
  else if (dataType === 'comment' || d.parentId || d.postId) {
    const commentBody = d.body || d.text || '';
    if (!commentBody || commentBody === '[deleted]' || commentBody === '[removed]') continue;

    // Apify가 제공하는 상위 게시물 ID(postId 또는 parentId)에서 순수 ID 추출
    const rawPostId = (d.postId || d.parentId || '').replace(/^t[13]_/, '');

    vocRows.push({
      json: {
        VOC_ID: `RD_CMT_${rawId}`,
        CATEGORY: category,
        CONTENT_TYPE: 'COMMENT',
        CONTENT: commentBody,
        PARENT_ID: rawPostId ? `RD_POST_${rawPostId}` : null
      }
    });
  }
}

return vocRows;
